<?php
require_once '../includes/auth.php';requireActiveUser();requireTenantContext();requireModulePermission('communication','create');global $conn;$tenantId=(int)getCurrentTenantId();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){requireCsrf();$name=trim($_POST['name']??'');$channel=$_POST['channel']??'sms';$subject=trim($_POST['subject']??'');$message=trim($_POST['message']??'');$status=$_POST['status']??'active';if($name===''||$message==='')$error='Name and message are required.';else{$q=$conn->prepare("INSERT INTO communication_templates(tenant_id,name,channel,subject,message,status) VALUES(?,?,?,?,?,?)");$q->bind_param('isssss',$tenantId,$name,$channel,$subject,$message,$status);if($q->execute())redirect('templates.php');$error=$q->error?:'Unable to save template.';$q->close();}}
$pageTitle='Add Communication Template';require_once '../includes/header.php';?><div class="dashboard-card"><h2>Add Template</h2><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post"><?=csrfField()?><div class="form-group"><label>Name</label><input name="name" required></div><div class="form-group"><label>Channel</label><select name="channel"><option value="sms">SMS</option><option value="whatsapp">WhatsApp</option><option value="email">Email</option></select></div><div class="form-group"><label>Subject</label><input name="subject"></div><div class="form-group"><label>Message</label><textarea name="message" rows="7" required></textarea></div><div class="form-group"><label>Status</label><select name="status"><option value="active">Active</option><option value="inactive">Inactive</option></select></div><button type="submit">Save Template</button> <a href="templates.php">Cancel</a></form></div><?php require_once '../includes/footer.php';?>